export const libraryArticles = libraryData.articles as LibraryArticle[];

export const libraryThemes = ((libraryData as { themes?: LibraryTheme[] })
  .themes ?? []) as LibraryTheme[];

export function getLibraryArticle(slug: string): LibraryArticle | undefined {
  return libraryArticles.find((article) => article.slug === slug);
}

export function getLibraryTheme(topicKey: string): LibraryTheme | undefined {
  if (isLibraryConditionOverlapTopic(topicKey)) return undefined;
  return libraryThemes.find((theme) => theme.topicKey === topicKey);
}

export function getAllLibrarySlugs(): string[] {
  return libraryArticles.map((article) => article.slug);
}

export function getLibraryArticleCount(): number {
  return libraryArticles.length;
}

/** Sheet URLs that should stay in the sitemap (single-sheet, indexable). */
export function getSitemapLibraryArticleSlugs(): string[] {
  return libraryArticles
    .filter(
      (article) =>
        !article.redirectsToTopic &&
        !article.needsReview &&
        !isLibraryConditionOverlapTopic(article.topicKey) &&
        !getLegacyLibrarySheetRedirect(article.slug),
    )
    .map((article) => article.slug);
}

export function getLibraryCategoryLabel(categoryId: string): string {
  return (
    libraryCategoryOrder.find((item) => item.id === categoryId)?.label ??
    categoryId
  );
}

export function getRelatedBlogForTopic(
  topicKey: string,
): LibraryRelatedBlog | undefined {
  const slug = libraryTopicBlogMap[topicKey];
  return slug ? getNutritionBlogMeta(slug) : undefined;
}

export function getLibraryArticlesByTopic(topicKey: string): LibraryArticle[] {
  return libraryArticles
    .filter((article) => article.topicKey === topicKey)
    .sort((a, b) => a.sourcePage - b.sourcePage);
}

export function articleRedirectsToTopic(article: LibraryArticle): boolean {
  if (article.redirectsToTopic) return true;
  return getLibraryArticlesByTopic(article.topicKey).length > 1;
}

export function getLibraryTopic(topicKey: string): LibraryTopic | undefined {
  if (isLibraryConditionOverlapTopic(topicKey)) return undefined;
  const articles = getLibraryArticlesByTopic(topicKey).filter(
    (article) => !isLibraryConditionOverlapTopic(article.topicKey),
  );
  if (articles.length === 0) return undefined;
  const lead = articles.find((article) => !article.needsReview) ?? articles[0];
  const theme = getLibraryTheme(topicKey);
  const publicArticles = articles.filter((article) => !article.needsReview);
  return {
    topicKey,
    title: lead.topicTitle || lead.title,
    category: lead.category,
    summary: theme?.summary ?? lead.summary,
    mskRelevant: articles.some((article) => article.mskRelevant),
    sheetCount: articles.length,
    needsReview: articles.every((article) => article.needsReview),
    articles: publicArticles.length > 0 ? publicArticles : articles,
    theme,
    relatedBlog: getRelatedBlogForTopic(topicKey),
  };
}

export function getAllLibraryTopicKeys(): string[] {
  const keys = new Set(
    libraryArticles
      .map((article) => article.topicKey)
      .filter((key) => !isLibraryConditionOverlapTopic(key)),
  );
  return [...keys].sort((a, b) => a.localeCompare(b));
}

/**
 * Topic hubs worth indexing: exclude needsReview stubs and single-sheet
 * topics (those already surface as the sheet URL from the library index).
 */
export function getSitemapLibraryTopicKeys(): string[] {
  return getAllLibraryTopicKeys().filter((key) => {
    if (isLibraryConditionOverlapTopic(key)) return false;
    const topic = getLibraryTopic(key);
    return Boolean(topic && !topic.needsReview && topic.sheetCount > 1);
  });
}

export function getLibraryTopicsByCategory(): {
  category: string;
  label: string;
  description: string;
  topics: LibraryTopic[];
}[] {
  const topicsByKey = new Map<string, LibraryTopic>();
  for (const key of getAllLibraryTopicKeys()) {
    const topic = getLibraryTopic(key);
    if (topic) topicsByKey.set(key, topic);
  }

  const groups: {
    category: string;
    label: string;
    description: string;
    topics: LibraryTopic[];
  }[] = libraryCategoryOrder
    .map((meta) => {
      const topics = [...topicsByKey.values()]
        .filter((topic) => topic.category === meta.id)
        .filter((topic) => !(topic.needsReview && meta.id !== "start-here"))
        .sort((a, b) => a.title.localeCompare(b.title));
      return {
        category: meta.id,
        label: meta.label,
        description: meta.description,
        topics,
      };
    })
    .filter((group) => group.topics.length > 0);

  const known = new Set(libraryCategoryOrder.map((item) => item.id));
  const extras = [...topicsByKey.values()].filter(
    (topic) => !known.has(topic.category as LibraryCategoryId),
  );
  if (extras.length > 0) {
    const byCat = new Map<string, LibraryTopic[]>();
    for (const topic of extras) {
      const list = byCat.get(topic.category) ?? [];
      list.push(topic);
      byCat.set(topic.category, list);
    }
    for (const [category, topics] of byCat) {
      groups.push({
        category,
        label: category,
        description: "",
        topics: topics.sort((a, b) => a.title.localeCompare(b.title)),
      });
    }
  }

  return groups;
}

/** Flat list of all sheets for the secondary “browse all” section. */
export function getAllLibraryArticlesSorted(): LibraryArticle[] {
  return [...libraryArticles].sort((a, b) => a.sourcePage - b.sourcePage);
}

/** @deprecated Prefer getLibraryTopicsByCategory for the organised hub. */
export function getLibraryArticlesBySection(): {
  section: string;
  label: string;
  articles: LibraryArticle[];
}[] {
  const order = [
    "front-matter",
    "contents",
    "products-a-z",
    "ailments",
    "sports-weight-loss",
    "sports",
    "weight-loss",
    "reference",
    "forms",
  ];
  const labels: Record<string, string> = {
    "front-matter": "Start here",
    contents: "Contents",
    "products-a-z": "Ingredients & themes A–Z",
    ailments: "Wellness themes",
    "sports-weight-loss": "Sports & weight themes",
    sports: "Sports",
    "weight-loss": "Weight themes",
    reference: "Reference",
    forms: "Forms & labels",
  };

  const bySection = new Map<string, LibraryArticle[]>();
  for (const article of libraryArticles) {
    const key = article.section || "general";
    const list = bySection.get(key) ?? [];
    list.push(article);
    bySection.set(key, list);
  }

  const groups = order
    .filter((key) => bySection.has(key))
    .map((key) => ({
      section: key,
      label: labels[key] ?? key,
      articles: bySection.get(key)!,
    }));

  for (const [key, articles] of bySection) {
    if (!order.includes(key)) {
      groups.push({ section: key, label: key, articles });
    }
  }
  return groups;
}
